 if(phase==='native'){keys=require('internal/crypto/keys');helpers=require('internal/crypto/util');publicKey=crypto;}
 else{const base=require(path.join(repo,'third_party/node-core/tests/crypto-key-usages/key-platform.cjs')).create();keys=base.privateKeys;publicKey=base;const source=fs.readFileSync(process.env.KEY_USAGE_CORE||path.join(repo,'third_party/node-core/node-core.js'),'utf8');const make=Function(source+';return typeof _createNodeCryptoKeyUsages==="function"?_createNodeCryptoKeyUsages:undefined;')();helpers=make?.();}
