 await group('own public usages and extractable cannot replace native rights',()=>{const k=make(1<<5);Object.defineProperty(k,'usages',{get(){throw Error('public usage read')}});Object.defineProperty(k,'extractable',{value:true});assert.equal(keys.hasCryptoKeyUsage(k,'deriveBits'),true);assert.equal(keys.hasCryptoKeyUsage(k,'sign'),false);assert.equal(keys.getCryptoKeyExtractable(k),false);const slots=rawKeys.getCryptoKeySlots(k);assert.equal(slots[1],false);assert.equal(slots[3],1<<5);return{actualExtractable:false,nativeExtractable:slots[1],mask:keys.getCryptoKeyUsagesMask(k),nativeMask:slots[3],publicExtractable:k.extractable};});
 await group('generic raw secret import owns exact original bytes',()=>{const bytes=Uint8Array.from([88,1,2,3,99]),view=bytes.subarray(1,4);const k=keys.importGenericSecretKey({name:'HKDF'},'raw',view,false,['deriveBits','deriveBits']);bytes.fill(7);assert.equal(util.types.isCryptoKey(k),true);assert.equal(k.type,'secret');assert.equal(k.extractable,false);assert.deepEqual(k.usages,['deriveBits']);const exported=publicKey.KeyObject.from(k).export();assert.deepEqual([...exported],[1,2,3]);return{bytes:[...exported],algorithm:k.algorithm,usages:k.usages,extractable:k.extractable};});
 await group('generic KeyObjectHandle import retains original material',()=>{const key=secret(Uint8Array.from([4,5,6]));const k=keys.importGenericSecretKey({name:'PBKDF2'},'KeyObjectHandle',handle(key),false,['deriveKey','deriveBits']);assert.equal(publicKey.KeyObject.from(k).equals(key),true);assert.equal(keys.getCryptoKeyUsagesMask(k),(1<<4)|(1<<5));return{sameMaterial:true,usages:k.usages,algorithm:k.algorithm};});
 await group('generic import rejects forbidden extractability and usages',()=>{const ex=ownError(()=>keys.importGenericSecretKey({name:'HKDF'},'raw',Uint8Array.of(1),true,['deriveBits']));const usage=ownError(()=>keys.importGenericSecretKey({name:'HKDF'},'raw',Uint8Array.of(1),false,['sign']));assert.equal(ex.name,'SyntaxError');assert.equal(usage.name,'SyntaxError');return{extractable:ex,usage};});
 await group('actual key import getter chronology and original exception',()=>{const trace=[],marker={original:true};const list=new Proxy(['deriveBits'],{get(target,key,receiver){trace.push('usage:'+String(key));if(key==='0')throw marker;return Reflect.get(target,key,receiver)}});let same=false;try{keys.importGenericSecretKey({get name(){trace.push('algorithm:name');return'HKDF'}},'raw',Uint8Array.of(1),true,list)}catch(e){same=e===marker}assert.equal(same,true);assert(!trace.includes('algorithm:name'));return{sameOriginal:true,trace};});
 await group('unsupported generic format preserves actual no-owner outcome',()=>{assert.equal(keys.importGenericSecretKey({name:'HKDF'},'spki',Uint8Array.of(1),false,['deriveBits']),undefined);return{noKey:true};});
 await group('zero mask is private import state, not public admission',()=>{const k=keys.importGenericSecretKey({name:'HKDF'},'raw-secret',Uint8Array.of(1),false,[]);assert.deepEqual(k.usages,[]);assert.equal(keys.getCryptoKeyUsagesMask(k),0);assert.equal(keys.hasCryptoKeyUsage(k,'deriveBits'),false);return{mask:0,privateHelperOnly:true};});
 await group('CryptoKey illegal constructor and getter brand checks',()=>{const ctor=ownError(()=>new keys.CryptoKey());const getter=Object.getOwnPropertyDescriptor(keys.CryptoKey.prototype,'usages').get;const fake=ownError(()=>Reflect.apply(getter,{},[]));assert.equal(ctor.code,'ERR_ILLEGAL_CONSTRUCTOR');assert.equal(fake.code,'ERR_INVALID_THIS');return{ctor,fake};});
 await group('set membership preserves exact target key coercion and exceptions',()=>{const trace=[],item={[Symbol.toPrimitive](hint){trace.push(hint);return'deriveBits'}};const mask=helpers.getUsagesMask(helpers.toUsagesSet([item,item]));assert.equal(mask,1<<5);assert.deepEqual(trace,['string']);const marker={original:true};let same=false;try{helpers.toUsagesSet({get length(){throw marker}})}catch(e){same=e===marker};assert(same);assert.equal(helpers.hasAnyNotIn(helpers.toUsagesSet(['deriveBits']),['deriveKey','deriveBits']),false);assert.equal(helpers.hasAnyNotIn(helpers.toUsagesSet(['sign']),['deriveBits']),true);return{mask,trace,sameOriginal:true};});
 console.log(JSON.stringify({phase,pass:rows.filter(x=>x.pass).length,fail:rows.filter(x=>!x.pass).length,rows,scope:'Pinned actual CryptoKey/KeyObject/secret-import wrappers and usage helpers over real native Node key handle/base-class/storage and explicit native Buffer/inspection/Values dependencies. New guest/native slots uncompiled/unexecuted; no public toCryptoKey/Subtle/WebIDL/provider/FIPS/algorithm/clone/four-host admission claim.'}));if(rows.some(x=>!x.pass))process.exitCode=1;
